package dev.thillainirmal.deeprag;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class RagLabTest{RagLab lab=new RagLab();@Test void runsSixPatterns(){var r=lab.run("repeated dependency failure","engineering");assertThat(r.trace()).hasSize(6);assertThat(r.hits()).isNotEmpty();}@Test void filtersMetadata(){assertThat(lab.run("latency connection pool","operations").hits()).allMatch(h->h.domain().equals("operations"));}@Test void expandsQuery(){assertThat(lab.run("failure","all").expandedQueries()).hasSize(3);}@Test void citesAnswer(){var r=lab.run("retry failure","engineering");assertThat(r.answer()).contains("[D");}}
